import React from 'react';
import styled from 'styled-components';
import Square from '../Square';
import ChessPiece from '../ChessPiece';
import { Board, Position, PieceColor } from '../../types/game';
import { WebSocketMessage, GameStateData, IMessage } from '../../types/websocket';

const BoardContainer = styled.div`
  display: grid;
  grid-template-columns: repeat(8, 1fr);
  width: 600px;
  height: 600px;
  border: 2px solid #333;
`;

interface ChessBoardProps {
  onMove: (from: Position, to: Position) => void;
  board: Board;
  lastMessage: IMessage | null;
  setBoard: (board: Board) => void;
  currentPlayer: PieceColor;
}

const ChessBoard: React.FC<ChessBoardProps> = ({ onMove, board, lastMessage, setBoard, currentPlayer }) => {
  const [selectedSquare, setSelectedSquare] = React.useState<Position | null>(null);

  useEffect(() => {
    if (lastMessage) {
      try {
        const message = JSON.parse(lastMessage.body || '') as WebSocketMessage;
        if (message.type === 'GAME_STATE') {
          const gameStateData = message.data as GameStateData;
          setBoard(gameStateData.board as Board);
        }
      } catch (error) {
        console.error('Error parsing message:', error);
      }
    }
  }, [lastMessage, setBoard]);

  const handleSquareClick = (position: Position) => {
    if (!selectedSquare) {
      const piece = board[position.row][position.col];
      if (piece && piece.color === currentPlayer) {
        setSelectedSquare(position);
      }
    } else {
      onMove(selectedSquare, position);
      setSelectedSquare(null);
    }
  };

  return (
    <BoardContainer>
      {board.map((row, rowIndex) =>
        row.map((piece, colIndex) => {
          const position: Position = { row: rowIndex, col: colIndex };
          const isSelected = selectedSquare?.row === rowIndex && selectedSquare?.col === colIndex;
          const isLight = (rowIndex + colIndex) % 2 === 0;

          return (
            <Square
              key={`${rowIndex}-${colIndex}`}
              piece={piece}
              isLight={isLight}
              isSelected={isSelected}
              onClick={() => handleSquareClick(position)}
            >
              {piece && (
                <ChessPiece
                  type={piece.type}
                  color={piece.color}
                />
              )}
            </Square>
          );
        })
      )}
    </BoardContainer>
  );
};

export default ChessBoard;
